sql.where:
AND OP.OrderState = '지불완료'
AND Ch.SvcCode = #{pSvcCode}
AND NOT EXISTS (
    SELECT 1 FROM shopwizard.tOrdUpriceMatch UM
    WHERE UM.ProdName = IFNULL(OP.ProdName, '') AND UM.ItemName = IFNULL(OP.ItemName, '')
)
AND O.ChnlCode = #{pChnlCode}
AND OP.ProdName LIKE CONCAT('%', #{pProdName}, '%')

     AND (O.OrderReciptDate >= DATE_FORMAT(#{pStartDate}, '%Y-%m-%d')
              AND O.OrderReciptDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y-%m-%d'), INTERVAL 1 DAY))

mapper.select:
SELECT IFNULL(OP.ProdName, '') AS prodName, IFNULL(OP.ItemName, '') AS itemName, COUNT(*) AS cnt, MIN(OP.OrderNo) AS sampleOrderNo, GROUP_CONCAT(DISTINCT Ch.ChnlName ORDER BY Ch.ChnlName SEPARATOR ', ') AS chnlNames, MAX(OP.RegistDate) AS lastRegistDate FROM shopion.tOrdOrderProd OP INNER JOIN shopion.tOrdOrder O ON OP.OrderNo = O.OrderNo INNER JOIN shopwizard.tCmpChnl Ch ON O.ChnlCode = Ch.ChnlCode
GROUP BY IFNULL(OP.ProdName, ''), IFNULL(OP.ItemName, '') ORDER BY cnt DESC, lastRegistDate DESC
LIMIT ${topCnt}, ${countPerPage}
